"""Merged identity groups."""


def merge_groups(records, merges):
    """Partition record IDs into merged groups using active merge links."""
    parent = {name: name for name in records}

    def root(name):
        while parent[name] != name:
            parent[name] = parent[parent[name]]
            name = parent[name]
        return name

    for link in merges.values():
        if link['active']:
            left, right = root(link['left']), root(link['right'])
            if left != right:
                parent[max(left, right)] = min(left, right)
    groups = {}
    for name in sorted(records):
        groups.setdefault(root(name), []).append(name)
    return {members[0]: members for members in groups.values()}


def group_load(members, records):
    return sum(records[name]['units'] for name in members)


def group_owners(members, records):
    owners = set(records[members[0]]['owners'])
    for name in members[1:]:
        owners &= set(records[name]['owners'])
    return sorted(owners)

"""Revision ledger access."""
import json
from pathlib import Path


def load(data_dir):
    data_dir = Path(data_dir)
    cutover = json.loads((data_dir / 'cutover.json').read_text())
    entries = json.loads((data_dir / 'ledger.json').read_text())['entries']
    check_unique(entries)
    return cutover, entries


def check_unique(entries):
    seen = set()
    for row in entries:
        key = (row['kind'], row['entity'], row['revision'])
        if key in seen:
            raise ValueError('duplicate ledger revision %s/%s/%s' % key)
        seen.add(key)


def latest(entries, kind):
    """Map each entity of `kind` to the value of its latest revision."""
    chosen = {}
    for row in entries:
        if row['kind'] == kind and (row['entity'] not in chosen or row['revision'] > chosen[row['entity']]['revision']):
            chosen[row['entity']] = row
    return {entity: row['value'] for entity, row in chosen.items()}

"""Steward assignment planning."""
from .groups import group_load, group_owners, merge_groups
from .ledger import latest


class PlanningError(Exception):
    """No assignment satisfies the rules."""


def assign_phase(groups, records, capacity):
    """Assign each group (largest load first) to the first qualified owner with room."""
    remaining = dict(capacity)
    result = {}
    for group_id in sorted(groups, key=lambda g: (-group_load(groups[g], records), g)):
        load = group_load(groups[group_id], records)
        for owner in group_owners(groups[group_id], records):
            if remaining.get(owner, 0) >= load:
                remaining[owner] -= load
                result[group_id] = owner
                break
        else:
            raise PlanningError('no qualified owner has room for %s' % group_id)
    return result


def plan(cutover, entries):
    records = latest(entries, 'record')
    capacity = {owner: value['units'] for owner, value in latest(entries, 'capacity').items()}
    groups = merge_groups(records, latest(entries, 'merge'))
    phases = [assign_phase(groups, records, capacity) for _ in cutover['phases']]
    return {
        'cutover': cutover['cutover'], 'customer': cutover['customer'], 'phases': list(cutover['phases']),
        'groups': [{'id': g, 'members': groups[g], 'owners': [phase[g] for phase in phases]} for g in sorted(groups)],
    }

