from .groups import group_load, group_owners, merge_groups
from .ledger import resolve


class PlanningError(Exception):
    """No assignment satisfies the rules."""


def phase_inputs(cutover, entries):
    """Resolve records, capacity and handoffs for every phase, and the merged groups frozen at phase 0."""
    cutoff = cutover['approval_cutoff']
    count = len(cutover['phases'])
    if count == 0:
        raise PlanningError('cutover has no phases')
    records = [resolve(entries, 'record', cutoff, k) for k in range(count)]
    names = set().union(*records)
    for k, phase_records in enumerate(records):
        missing = sorted(names - set(phase_records))
        if missing:
            raise PlanningError('no applicable record revision in phase %d for %s' % (k, ', '.join(missing)))
    merges = resolve(entries, 'merge', cutoff, 0)
    for entity, link in merges.items():
        if link['active'] and not {link['left'], link['right']} <= names:
            raise PlanningError('merge %s links an unknown record' % entity)
    groups = merge_groups(names, merges)
    member_group = {name: group_id for group_id, members in groups.items() for name in members}
    capacity = [{owner: value['units'] for owner, value in resolve(entries, 'capacity', cutoff, k).items()}
                for k in range(count)]
    transfers = []
    for k in range(count - 1):
        allowed = set()
        for entity, handoff in resolve(entries, 'handoff', cutoff, k).items():
            if not handoff['active'] or handoff['boundary'] != k:
                continue
            if handoff['record'] not in member_group:
                raise PlanningError('handoff %s names an unknown record' % entity)
            allowed.add((member_group[handoff['record']], handoff['from'], handoff['to']))
        transfers.append(allowed)
    return groups, records, capacity, transfers


def plan_assignments(groups, records, capacity, transfers):
    """Search for one steward per group per phase satisfying qualification, capacity and continuity.

    Returns a list (one dict per phase) mapping group ID to owner, or raises PlanningError.
    """
    count = len(records)
    order = sorted(groups)
    load = [{g: group_load(groups[g], records[k]) for g in order} for k in range(count)]
    qualified = [{g: group_owners(groups[g], records[k]) for g in order} for k in range(count)]
    dead = set()

    def candidates(k, group_id, previous):
        options = qualified[k][group_id]
        if previous is None:
            return options
        before = previous[group_id]
        return [o for o in options if o == before or (group_id, before, o) in transfers[k - 1]]

    def phases_from(k, previous):
        if k == count:
            return []
        key = (k, None if previous is None else tuple(previous[g] for g in order))
        if key in dead:
            return None
        for assignment in phase_options(k, previous):
            rest = phases_from(k + 1, assignment)
            if rest is not None:
                return [assignment] + rest
        dead.add(key)
