        remaining = dict(capacity[k])
        current = {}

        def place(index):
            if index == len(order):
                yield dict(current)
                return
            group_id = order[index]
            need = load[k][group_id]
            for owner in candidates(k, group_id, previous):
                if remaining.get(owner, 0) >= need:
                    remaining[owner] -= need
                    current[group_id] = owner
                    yield from place(index + 1)
                    del current[group_id]
                    remaining[owner] += need

